"""Test 17: the per-shot read (t17-rule.md section 4) and the middle test (section 5), on this run's arrays in
this test existed.


0. Every array and meta file's SHA-256 against shots-t17-hashes-before-analysis.txt; a mismatch stops that job.
1. Each published counts file (counts-t17-<key>.json, the fetched record with its usage key removed) against the
   private record it was copied from (its SHA-256 at copy), and the counts recomputed from each array against it,
   position for position (read_t15.counts_check, inside read_monitor); a mismatch stops that job.
2. Section 4: read_t15.read_monitor per span, both quadratures, the quadrature of record named; the job's word
   (read_t15.job_word); the boundary words at every adjacent pair of spans (read_t15.boundary_rows) with both
   sensitivities and the published weight differences of fits-t17-counts.json over the same sd beside; between adjacent
   jobs (read_t15.between_jobs, its keys relabelled) with the stamp on the row.
3. Section 5, the middle test, for each job with three or more spans:
   t = (span centre in time - first span's start) / (last span's stop - first span's start), the centre being the
   midpoint of the span's start and stop as the execution record gives them;
   C = mean duty (test 15's threshold duty b, never folded) of the spans with t in [1/3, 2/3] minus the mean duty of the
   other spans; sd(C) = sqrt(sd_mid^2 + sd_other^2), each mean's sd = sqrt(sum of its spans' telegraph sd^2) / its count;
   a job with no span centre in [1/3, 2/3] contributes no contrast and is listed; ruling 3: a job with any span not
   SHARED contributes no contrast and is listed;
   Z = (sum of C_j / sd_j) / sqrt(n) over the n contributing jobs; MIDDLE HIGH if Z >= 2.0, NOT SEEN if Z < 1.0,
   UNDECIDED between.
   Beside, no word: the per-span duties against t; a weighted straight line of duty on t (weights 1 / sd^2) and its
   slope over its sd; for Part B the duty of each span against its index; the contrast at the threshold sensitivity
   (test 15's 20th to 80th midpoint duty and its telegraph sd).
   The middle-test functions are imported by the section 9 check (desk_t17.py), so the synthetic sets are read by the
   same code.

Usage: python -I -B read_t17.py [--out fits-t17-shots.json]"""
from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import hashlib  # noqa: E402
import importlib.util  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from datetime import datetime  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
OUT = HB / "t17"
T15 = HB / "t15"
KEYS = ["A1", "A2", "A3", "B1"]
Z_HIGH, Z_LOW = 2.0, 1.0
MID = (1 / 3, 2 / 3)
R15 = None


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00"))




# ---------------------------------------------------------------- 0 and 1

def check_hashes():
    rec = {}
    p = OUT / "shots-t17-hashes-before-analysis.txt"
    for line in p.read_text().splitlines():
        parts = line.split()
        if len(parts) >= 2 and len(parts[0]) == 64:
            rec[parts[1]] = parts[0]
    out = {name: {"recorded": h, "now": sha(OUT / name), "equal": sha(OUT / name) == h} for name, h in rec.items()}
    ok = {k: sum(n.startswith(f"shots-t17-{k}") for n in out) == 2 and all(v["equal"] for n, v in out.items() if n.startswith(f"shots-t17-{k}"))
          for k in KEYS}
    return out, ok


def counts_copy_check(key):
    """The published counts file against the record it was copied from."""
    cp = json.loads((OUT / "copies-t17.json").read_text()) if (OUT / "copies-t17.json").exists() else {}
    c = cp.get(key)
    if not c:
        return {"pass": False, "note": "no copy record"}
    now = sha(OUT / f"counts-t17-{key}.json")
    return {"pass": now == c["copied_sha256"], "copied_sha256": c["copied_sha256"], "now": now, "as_fetched_sha256": c["as_fetched_sha256"],
            "removed": c["removed"]}


# ---------------------------------------------------------------- section 5

def record_spans(job):
    wd = job["qubits"]["143"]["waits"]["monitor"]
    q = wd["quadrature_of_record"]
    return wd, q, [s for s in wd["spans"] if q in s]


def span_times(job):
    """Each span's normalized centre t, from the execution record's starts and stops."""
    sp = sorted(job["spans"], key=lambda s: s["start_utc"])
    t0, t1 = ts(sp[0]["start_utc"]), ts(sp[-1]["stop_utc"])
    L = (t1 - t0).total_seconds()
    return {s["span"]: ((ts(s["start_utc"]) - t0).total_seconds() + (ts(s["stop_utc"]) - ts(s["start_utc"])).total_seconds() / 2) / L for s in sp}


def contrast(rows, duty_key="duty", sd_key="sd"):
    """C and its sd from rows of {t, duty, sd}; None if no span centre lies in [1/3, 2/3] or none outside it."""
    mid = [r for r in rows if MID[0] <= r["t"] <= MID[1]]
    oth = [r for r in rows if not (MID[0] <= r["t"] <= MID[1])]
    if not mid or not oth:
        return None
    m_mid = float(np.mean([r[duty_key] for r in mid]))
    m_oth = float(np.mean([r[duty_key] for r in oth]))
    sd_mid = math.sqrt(sum(r[sd_key] ** 2 for r in mid)) / len(mid)
    sd_oth = math.sqrt(sum(r[sd_key] ** 2 for r in oth)) / len(oth)
    C = m_mid - m_oth
    sd = math.hypot(sd_mid, sd_oth)
    return {"C": C, "sd": sd, "C_over_sd": C / sd, "mean_mid": m_mid, "mean_other": m_oth, "sd_mid": sd_mid, "sd_other": sd_oth,
            "mid_spans": [r["span"] for r in mid], "other_spans": [r["span"] for r in oth]}


def wline(t, y, sd):
    t, y, w = np.asarray(t, float), np.asarray(y, float), 1 / np.asarray(sd, float) ** 2
    if len(t) < 3:
        return None
    X = np.stack([np.ones_like(t), t], axis=1)
    G = X.T @ (X * w[:, None])
    a0, b0 = np.linalg.solve(G, X.T @ (w * y))
    se = math.sqrt(np.linalg.inv(G)[1, 1])
    return {"intercept": float(a0), "slope_per_unit_t": float(b0), "slope_sd": se, "slope_over_sd": float(b0) / se}


def middle_job(key, span_rows, n_spans):
    """span_rows: per span {span, t, word, duty, sd, duty_2080, sd_2080, w_branch}. Returns the job's row of the middle test."""
    row = {"job": key, "n_spans": n_spans, "spans": span_rows}
    if n_spans < 3:
        row.update({"contributes": False, "reason": "fewer than three spans"})
        return row
    not_shared = [r["span"] for r in span_rows if r["word"] != "SHARED"]
    if not_shared:
        row.update({"contributes": False, "reason": f"ruling 3: spans {not_shared} are not SHARED, so they carry no telegraph sd"})
        return row
    c = contrast(span_rows)
    if c is None:
        row.update({"contributes": False, "reason": "no span centre in [1/3, 2/3] (or none outside it)"})
        return row
    row.update({"contributes": True, **c})
    c2 = contrast(span_rows, "duty_2080", "sd_2080")
    row["beside_threshold_20_80"] = c2
    row["beside_line_duty_on_t"] = wline([r["t"] for r in span_rows], [r["duty"] for r in span_rows], [r["sd"] for r in span_rows])
    return row


def pooled(rows):
    used = [r for r in rows if r.get("contributes")]
    n = len(used)
    if not n:
        return {"n_contributing_jobs": 0, "Z": None, "word": None, "note": "no job contributes a contrast"}
    Z = sum(r["C_over_sd"] for r in used) / math.sqrt(n)
    word = "MIDDLE HIGH" if Z >= Z_HIGH else ("NOT SEEN" if Z < Z_LOW else "UNDECIDED")
    out = {"n_contributing_jobs": n, "contributing": [r["job"] for r in used], "listed_not_contributing": [(r["job"], r["reason"]) for r in rows if not r.get("contributes")],
           "Z": Z, "word": word}
    u2 = [r["beside_threshold_20_80"] for r in used if r.get("beside_threshold_20_80")]
    if len(u2) == n:
        out["beside_Z_at_threshold_20_80"] = sum(x["C_over_sd"] for x in u2) / math.sqrt(n)
    return out


def span_rows_of(job):
    wd, q, sp = record_spans(job)
    tt = span_times(job)
    rows = []
    for s in sp:
        r = s[q]
        rows.append({"span": s["span"], "t": tt[s["span"]], "word": r.get("word"), "duty": r.get("duty_b"), "sd": r.get("telegraph_sd"),
                     "sd_is_ceiling": r.get("tau_c_ceiling"), "duty_2080": r.get("duty_b_at_threshold_20_80"),
                     "sd_2080": r.get("telegraph_sd_at_threshold_20_80"), "w_branch": s.get("w_branch"), "n_whole_repeats": s.get("n_whole_repeats")})
    return rows, len(job["spans"])


# ---------------------------------------------------------------- the published level changes of this run

def published_from_counts():
    f = json.loads((OUT / "fits-t17-counts.json").read_text())
    pub = {}
    for key, j in f["jobs"].items():
        if "analysis" not in j:
            continue
        wps = {s["span"]: s for s in j["analysis"]["weight_per_span"]}
        pub[key] = [{"spans": x["spans"], "w": [wps[x["spans"][0]]["mean_w"], wps[x["spans"][1]]["mean_w"]], "difference": x["difference"],
                     "error": x["error"], "in_errors": x["in_errors"], "source": "fits-t17-counts.json, level_changes"} for x in j["analysis"]["level_changes"]]
    return pub


# ---------------------------------------------------------------- main
